#ifndef TRITON_TO_GRAPH_TT_OP_SEMANTICS_DSL_H
#define TRITON_TO_GRAPH_TT_OP_SEMANTICS_DSL_H

#include "TritonToGraph/AutoGraphSolver.h"
#include "TritonToGraph/GraphOptimization.h"

#include "mlir/IR/BuiltinAttributes.h"
#include "llvm/ADT/ArrayRef.h"
#include "llvm/ADT/SmallVector.h"

#include <functional>
#include <string>

namespace mlir::triton::cfg {

struct TTIRCandidateAttributeBinding {
  enum class StorageKind : uint8_t { Inferred, I32, I64Array };

  std::string attributeName;
  std::string domainName;
  StorageKind storageKind = StorageKind::Inferred;
};

enum class TTIRCandidateEffectKind : uint8_t {
  Pure,
  Read,
  Write,
  Atomic,
  Observable,
  BufferRead,
  BufferWrite,
};

// Implicit proof-state inputs are not real MLIR operands. They make global
// execution contracts explicit in the offline language without teaching the
// enumerator individual operation names.
enum class TTIRCandidateStateDomain : uint8_t {
  Memory,
  Launch,
  Buffer,
};

struct TTIRCandidateOperandEffectRequirement {
  unsigned operandIndex = 0;
  TTIRCandidateEffectKind effectKind = TTIRCandidateEffectKind::Pure;
};

// One executable candidate form parsed from TTOpSemantics. The callbacks are
// generated by the generic constraint interpreter; they never contain
// operation-specific C++ logic.
struct TTIRCandidateOpSchema {
  std::string operationName;
  // Stable source-order identity of the declarative `semantics` clause.  A
  // single operation may have several arities, result projections or region
  // bodies; operation-name coverage alone must not hide an unreachable
  // overload.
  unsigned semanticClauseIndex = 0;
  unsigned operandCount = 0;
  // A multi-result MLIR operation is represented by one graph projection per
  // result.  Every projection carries the complete operation result signature
  // so the generic materializer recreates all results and returns this one.
  // Single-result operations keep resultIndex=0 and return {resultType}.
  unsigned resultIndex = 0;
  unsigned operationResultCount = 1;
  // State operands are proof-language edges appended after the real MLIR
  // operands. They are discovered from declarative state_operand(...) calls.
  SmallVector<TTIRCandidateStateDomain, 2> implicitStateDomains;
  std::optional<TTIRCandidateStateDomain> producedStateDomain;
  // Offline semantic graphs append one implicit MemoryState operand to every
  // read/write/atomic node. This keeps ordering and alias-sensitive values in
  // the graph without changing the real TTIR operation arity used online.
  TTIRCandidateEffectKind effectKind = TTIRCandidateEffectKind::Pure;
  // Every semantic overload has a schema record. This flag is false when the
  // `.ttsem` overload has no candidate clause, allowing offline completeness
  // reports to identify the exact missing arity without making it enumerable.
  bool constructible = false;
  bool intentionalImportOnly = false;
  bool structuralRegionOnly = false;
  // Transitional staging control: the offline rule generator must see the
  // full construction language, while the legacy bounded online beam keeps
  // its established candidate set until it is replaced by database lookup.
  bool offlineOnly = false;
  // Online-POC staging guard. The legacy online beam may only reuse such an
  // operation after observing it in the island. Offline bounded enumeration
  // still constructs it from the complete semantic schema and finite domains.
  bool requiresWitnessedOperation = false;
  // Exploratory constructors may be retained before they have proved equal
  // to an existing e-class.  This is required for multi-step discovery (for
  // example build a linear pointer, then a masked load) and remains bounded
  // by the common candidate/e-node budgets.
  bool exploratory = false;
  // The node participates in proof/search but has no concrete MLIR operation.
  // This is declared by `materialize = proof_only` in TTOpSemantics rather
  // than recognized by operation name in the generic materializer.
  bool proofOnlyMaterialization = false;
  // Extracted generically from `attribute(name, domain)` calls in the
  // candidate clause. The offline enumerator resolves the named finite domain
  // from GraphUniverseSpec and enumerates its Cartesian product.
  SmallVector<TTIRCandidateAttributeBinding, 4> attributeBindings;
  // Attributes referenced by import/value semantics are part of canonical
  // identity even for a non-constructible import-only schema.
  SmallVector<std::string, 4> semanticAttributeNames;
  // Declarative producer-class constraints such as
  // `producer_effect(input, atomic)`. They let proof-only projections and
  // future state combinators remain generic without accepting every typed
  // value in the Cartesian product.
  SmallVector<TTIRCandidateOperandEffectRequirement, 2>
      operandEffectRequirements;
  GraphOptimizationRuleId planId = GraphOptimizationRuleId::AutoGraphSolver;
  std::function<bool(Type resultType, DictionaryAttr attributes)>
      canProduceResult;
  // Selects the exact declarative overload for a concrete imported operation.
  // This prevents same-name/same-arity clauses (for example pure and impure
  // external calls) from being classified by source order.
  std::function<bool(Operation *operation)> matchesOperation;
  std::function<bool(Type resultType, ArrayRef<Type> operandTypePrefix,
                     DictionaryAttr attributes)>
      mayBeWellTyped;
  // Checks an arbitrary partial operand assignment. Null Type entries denote
  // unassigned operands. This lets the offline enumerator use a generic
  // fail-first CSP search instead of being forced through operand order and
  // visiting TypeDomain^arity for constraints on late operands.
  std::function<bool(Type resultType, ArrayRef<Type> operandTypeAssignment,
                     DictionaryAttr attributes)>
      mayBeWellTypedAssignment;
  std::function<bool(Type resultType, ArrayRef<Type> operandTypes,
                     DictionaryAttr attributes)>
      isWellTyped;
  std::function<SmallVector<Type, 2>(Type resultType,
                                     ArrayRef<Type> operandTypes,
                                     DictionaryAttr attributes)>
      buildOperationResultTypes;
  // Optional compiler/module action emitted by a proof-only state node. The
  // generic online materializer applies the resulting name/value dictionary
  // only after the value/effect rewrite succeeds.
  std::function<DictionaryAttr(DictionaryAttr attributes)>
      buildModuleAttributePatch;
  // Optional executable compiler action emitted by a proof-only node. The
  // action kind and all operands are declared in `.ttsem`; the online engine
  // interprets this small generic action vocabulary after exact RuleDB match.
  std::function<DictionaryAttr(DictionaryAttr attributes)> buildCompilerAction;
  // Optional generic region recipe generated from the declarative `region`
  // field. It is evaluated only after operand types are known and is stored in
  // the canonical graph just like any other semantic attribute.
  std::function<ArrayAttr(Type resultType, ArrayRef<Type> operandTypes,
                          DictionaryAttr attributes)>
      buildRegions;
};

// Parses the built-in .ttsem source. `import` implements Signature; the result
// type plus the generic indexed evaluator implement Shape/Index; `value` and
// `valid` implement Value/Definedness. `candidate` describes legal construction
// during search and is deliberately not an optimization pattern. Adding an
// operation must not require a candidate-discovery code change.
TTOpSemanticsRegistry createBuiltinTTOpSemanticsRegistry();

// Version key for the exact declarative semantics source compiled into this
// binary. Persistent proof/e-class artifacts must match it before reuse.
std::string getBuiltinTTOpSemanticsStableHash();

SmallVector<TTIRCandidateOpSchema, 4>
createBuiltinTTIRCandidateOpSchemas(const GraphOptimizationOptions &options,
                                    unsigned maxCandidateOperands = 16);

} // namespace mlir::triton::cfg

#endif // TRITON_TO_GRAPH_TT_OP_SEMANTICS_DSL_H
